#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    long long maxCaloriesBurnt(vector<int>& heights) {
        vector<int> a = heights;
        sort(a.begin(), a.end());
        int l = 0, r = (int)a.size() - 1;
        long long last = 0, ans = 0;
        bool high = true;
        while (l <= r) {
            long long v = high ? a[r--] : a[l++];
            long long d = v - last;
            ans += d * d;
            last = v;
            high = !high;
        }
        return ans;
    }
};
